import{_ as p,a0 as h,w as o,s as r,ao as t,I as i,x as s,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何入門 Linux Shell 腳本編寫 | LCTT x X-CMD","titleTemplate":false,"description":"如何入門 Linux Shell 腳本編寫 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何入門 Linux Shell 腳本編寫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何入門 Linux Shell 腳本編寫 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20221015.1 ⭐️⭐️ How to Get Started with Shell Scripting in Linux","title":"如何入門 Linux Shell 腳本編寫","tag":"202305","desc":""},"relativePath":"202305/20221015.1 ⭐️⭐️ How to Get Started with Shell Scripting in Linux.md","filePath":"[post].md"}'),d={name:"202305/20221015.1 ⭐️⭐️ How to Get Started with Shell Scripting in Linux.md"};function u(S,l,m,b,c,g){const e=h("Link");return o(),r("div",null,[l[35]||(l[35]=t('<h1 id="如何入門-linux-shell-腳本編寫" tabindex="-1">如何入門 Linux Shell 腳本編寫 <a class="header-anchor" href="#如何入門-linux-shell-腳本編寫" aria-label="Permalink to “如何入門 Linux Shell 腳本編寫”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202305/19/235745hz7r48umu1eerm2e.jpg" alt=""></p><blockquote><p>各位讀者，我們將在本文中介紹如何在 Linux 或 UNIX 系統中入門 Shell 腳本編寫。</p></blockquote><h3 id="什麼是-shell-呢" tabindex="-1">什麼是 Shell 呢？ <a class="header-anchor" href="#什麼是-shell-呢" aria-label="Permalink to “什麼是 Shell 呢？”">​</a></h3>',4)),i("p",null,[l[1]||(l[1]=s("Shell（交互界面）是類 UNIX/Linux 操作系統中的一個解釋器。它將用户輸入的命令解釋成操作系統的系統調用來執行這些命令。簡單來説，Shell 形式上是操作系統的包裝。比如，你可能使用 Shell 命令來列出目錄中的文件，如 ",-1)),a(e,{href:"https://www.linuxtechi.com/linux-ls-command-examples-beginners/"},{default:n(()=>[...l[0]||(l[0]=[s("ls",-1)])]),_:1}),l[2]||(l[2]=s(" 命令，或使用命令複製，如 ",-1)),l[3]||(l[3]=i("code",null,"cp",-1)),l[4]||(l[4]=s(" 命令。",-1))]),l[36]||(l[36]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>Desktop Documents Downloads Music Pictures playbook.yaml Public snap Templates test5 Videos</span></span></code></pre></div><p>在上方的例子中，當你輸入 <code>ls</code> 並按下回車鍵。<code>$</code> 符號是 Shell 的提示符，意味着 Shell 等着命令的輸入。下面的一行就是當前目錄下的文件名。</p><h3 id="什麼是-shell-提示符" tabindex="-1">什麼是 Shell 提示符？ <a class="header-anchor" href="#什麼是-shell-提示符" aria-label="Permalink to “什麼是 Shell 提示符？”">​</a></h3>`,3)),i("p",null,[l[6]||(l[6]=s("提示符，即 ",-1)),l[7]||(l[7]=i("code",null,"$",-1)),l[8]||(l[8]=s("，被稱作命令提示符，是由 Shell 發出的（LCTT 譯註：這個概念，可能有誤。請參看：",-1)),a(e,{href:"https://www.gnu.org/savannah-checkouts/gnu/bash/manual/bash.html#Controlling-the-Prompt%EF%BC%89%E3%80%82%E7%95%B6%E6%8F%90%E7%A4%BA%E7%AC%A6%E5%87%BA%E7%8F%BE%E5%BE%8C%EF%BC%88LCTT"},{default:n(()=>[...l[5]||(l[5]=[s("https://www.gnu.org/savannah-checkouts/gnu/bash/manual/bash.html#Controlling-the-Prompt）。當提示符出現後（LCTT",-1)])]),_:1}),l[9]||(l[9]=s(" 譯註：此處提示符並不特指 ",-1)),l[10]||(l[10]=i("code",null,"$",-1)),l[11]||(l[11]=s(" 符號），你就可以輸入命令了。Shell 將會在你按下回車鍵後讀取你的輸入。它會通過查看你輸入的第一個單詞來確定你希望執行的命令。“單詞”指的是一組連續的字符。空格和製表符作為分割單詞的標誌。",-1))]),l[37]||(l[37]=t(`<h3 id="不同類型的-shell" tabindex="-1">不同類型的 Shell <a class="header-anchor" href="#不同類型的-shell" aria-label="Permalink to “不同類型的 Shell”">​</a></h3><p>由於沒有限制只能有一個 Shell，你可以按照自己的意願來自由選擇運行任何一種 Shell。這當然挺好的，但是在不清楚其它替代方案的情況下選擇一種 Shell 沒有多大益處。下面列出了一些 UNIx/Linux 下常見的 Shell。</p><h4 id="sh-bourne-shell" tabindex="-1">Sh（Bourne Shell） <a class="header-anchor" href="#sh-bourne-shell" aria-label="Permalink to “Sh（Bourne Shell）”">​</a></h4><p>最初的 Unix Shell 通常被稱作 Sh，是 Shell（或 Bourne Shell）的簡寫，以其作者 Steven Bourne 命名。它在幾乎所有的類 UNIX 操作系統下都可以找到。基本的 Bourne Shell 僅支持相當有限的命令列編輯。你可以輸入字符，使用退格鍵刪除字符，還有就是按下回車鍵來執行命令。當命令列出現異常了，你可以按下 <code>Ctrl-C</code> 組合鍵來終止整個命令。</p><h4 id="csh-c-shell" tabindex="-1">Csh（C Shell） <a class="header-anchor" href="#csh-c-shell" aria-label="Permalink to “Csh（C Shell）”">​</a></h4><p>它是由加利福尼亞大學伯克利分校的 Bill Joy 設計的，由於它的語法和 C 語言相似，所以被命名為 C Shell。這種 Shell 在 Bourne shell 的基礎上增加了一些實用功能，尤其是可以重用之前的命令來幫助創建之後要執行的命令。當你去完成一項專門任務的時候，大多數的情況下需要執行不止一條命令，這樣 C shell 的能力就相當有用了。</p><h4 id="ksh-korn-shell" tabindex="-1">Ksh（Korn Shell） <a class="header-anchor" href="#ksh-korn-shell" aria-label="Permalink to “Ksh（Korn Shell）”">​</a></h4><p>它是由貝爾實驗室的 David Korn 創造的，Korn Shell 提供了和 C Shell 相同的增強，其中有一項重要的不同：Korn Shell 提供了對舊的 Bourne Shell 語法的向後兼容。在 Unix 下，如 AIX &amp; HP-UX 上，Korn Shell 是默認 Shell。</p><h4 id="bash-bourne-again-shell" tabindex="-1">Bash（Bourne Again Shell） <a class="header-anchor" href="#bash-bourne-again-shell" aria-label="Permalink to “Bash（Bourne Again Shell）”">​</a></h4><p>Bash 提供了像 Korn Shell 一樣的命令列編輯，像 C Shell 一樣的文件名補全和許多其它的高級功能。許多用户認為 Bash 集 Korn Shell 和 C Shell 的優點於一身。在 Linux 和 Mac OS X 系統下，Bash 是默認的 Shell。</p><h4 id="tcsh-t-c-shell" tabindex="-1">Tcsh（T C Shell） <a class="header-anchor" href="#tcsh-t-c-shell" aria-label="Permalink to “Tcsh（T C Shell）”">​</a></h4><p>Linux 系統推廣了 Tcsh。Tcsh 擴展了傳統的 csh，增加了命令列編輯、文件名補全和其它功能。例如，當你按下 <code>Tab</code> 鍵後，Tcsh 會補全文件和目錄名（與 Bash 中的按鍵相同）。舊的 C Shell 不支持這項功能。</p><h3 id="什麼是-shell-腳本呢" tabindex="-1">什麼是 Shell 腳本呢？ <a class="header-anchor" href="#什麼是-shell-腳本呢" aria-label="Permalink to “什麼是 Shell 腳本呢？”">​</a></h3><p>Shell 腳本是包含一條或多條命令的文本文件。在 Shell 腳本中，Shell 程序假定文本文件的每一行是一條不同的命令。這些命令的大部分就和你在 Shell 窗口手動輸入的一樣。</p><h4 id="為什麼要使用-shell-腳本呢" tabindex="-1">為什麼要使用 Shell 腳本呢？ <a class="header-anchor" href="#為什麼要使用-shell-腳本呢" aria-label="Permalink to “為什麼要使用 Shell 腳本呢？”">​</a></h4><p>Shell 腳本被用來自動化管理任務、簡化複雜的配置細節，並且充分運用操作系統的性能。有了組合不同命令的能力就可以創造新命令了，從而增加操作系統的價值。此外，結合使用 Shell 與圖形化桌面環境，可以兼得二者之長。</p><p>從系統管理員的角度看，日復一日的重複工作可以使用 Shell 腳本來實現自動處理，那就可以節約時間從事其它高質量的工作。</p><h3 id="創建第一個-shell-腳本" tabindex="-1">創建第一個 Shell 腳本 <a class="header-anchor" href="#創建第一個-shell-腳本" aria-label="Permalink to “創建第一個 Shell 腳本”">​</a></h3><p>在當前工作目錄下創建一個名為 <code>myscript.sh</code> 的文本文件，所有的 Shell 腳本都有 <code>.sh</code> 的擴展名（LCTT 譯註：Linux 下根本沒有擴展名一説，沒有這個擴展一樣是可以執行的）。腳本的第一行是 <code>#!/bin/sh</code> 或 <code>#!/bin/bash</code>，因為 <code>#</code> 符號被稱作 “hash” 並且 <code>!</code> 符號被稱作 “bang” 故被稱為 shebang（釋伴）。至於 <code>/bin/sh</code> 和 <code>/bin/bash</code> 則指出了命令將被 Sh 還是 Bash shell 執行。</p><p>以下就是 <code>myscript.sh</code> 的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span># Written by LinuxTechi</span></span>
<span class="line"><span>echo</span></span>
<span class="line"><span>echo &quot;Current Working Directory: $(pwd)&quot;</span></span>
<span class="line"><span>echo</span></span>
<span class="line"><span>echo &quot;Today&#39; Date &amp; Time: $(date)&quot;</span></span>
<span class="line"><span>DISK=$(df -Th)</span></span>
<span class="line"><span>echo</span></span>
<span class="line"><span>echo &quot;Disk Space on System:&quot;</span></span>
<span class="line"><span>echo &quot;$DISK&quot;</span></span></code></pre></div>`,21)),i("p",null,[l[14]||(l[14]=s("上方的腳本將會展示當前工作目錄、今天的日期與時間，還有磁盤空間。我們需要用到 ",-1)),a(e,{href:"https://www.linuxtechi.com/echo-command-examples-in-linux/"},{default:n(()=>[...l[12]||(l[12]=[s("echo 命令",-1)])]),_:1}),l[15]||(l[15]=s(" 和其它 ",-1)),a(e,{href:"https://www.linuxtechi.com/20-linux-commands-interview-questions-answers/"},{default:n(()=>[...l[13]||(l[13]=[s("Linux 命令",-1)])]),_:1}),l[16]||(l[16]=s(" 來實現這個腳本。",-1))]),i("p",null,[l[18]||(l[18]=s("使用如下的 ",-1)),a(e,{href:"https://www.linuxtechi.com/chmod-command-examples-in-linux/"},{default:n(()=>[...l[17]||(l[17]=[s("chmod 命令",-1)])]),_:1}),l[19]||(l[19]=s(" 來給文件增加執行權限：",-1))]),l[38]||(l[38]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod a+x myscript.sh</span></span></code></pre></div><p>現在來執行腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sh myscript.sh</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span>$ ./myscript.sh</span></span></code></pre></div><p>注意：在當前目錄下執行當前目錄下的 Shell 腳本，須使用 <code>./&lt;腳本名&gt;</code> 方式，如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2014/03/shell-script-contents-linux.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><h4 id="在-shell-腳本中獲取用户輸入" tabindex="-1">在 Shell 腳本中獲取用户輸入 <a class="header-anchor" href="#在-shell-腳本中獲取用户輸入" aria-label="Permalink to “在 Shell 腳本中獲取用户輸入”">​</a></h4><p><code>read</code> 命令用來獲取用户的鍵盤輸入，並且將之賦值給一個變量。<code>echo</code> 命令用來展示內容。</p><p>讓我們更改上方的腳本以使之獲取輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span># Written by LinuxTechi</span></span>
<span class="line"><span>read -p &quot;Your Name: &quot; NAME</span></span>
<span class="line"><span>echo</span></span>
<span class="line"><span>echo &quot;Today&#39; Date &amp; Time: $(date)&quot;</span></span>
<span class="line"><span>echo</span></span>
<span class="line"><span>read -p &quot;Enter the file system:&quot; DISK</span></span>
<span class="line"><span>echo &quot;$(df -Th $DISK)&quot;&quot;</span></span></code></pre></div><p>現在，再執行腳本試試，這回應該會有輸入信息的提醒：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./myscript.sh</span></span>
<span class="line"><span>Your Name: Pradeep Kumar</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Today&#39; Date &amp; Time: Sat 15 Oct 05:32:38 BST 2022</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Enter the file system:/mnt/data</span></span>
<span class="line"><span>Filesystem Type Size Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/mapper/volgrp01-lv01 ext4 14G 24K 13G 1% /mnt/data</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2014/03/Input-Read-Shell-Script-Examples.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>完美，上方的輸出表明腳本有輸入提醒，並加工處理了相應的數據。</p><p>本文結束。希望對你是有用的。非常歡迎任何的疑問、反饋。</p><p><em>（題圖：MJ/f83b771e-a70d-4c62-a169-ec42e9004a14）</em></p><hr>`,16)),i("p",null,[l[21]||(l[21]=s("via: ",-1)),a(e,{href:"https://www.linuxtechi.com/get-started-shell-scripting-linux/"},{default:n(()=>[...l[20]||(l[20]=[s("https://www.linuxtechi.com/get-started-shell-scripting-linux/",-1)])]),_:1})]),i("p",null,[l[26]||(l[26]=s("作者：",-1)),a(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...l[22]||(l[22]=[s("Pradeep Kumar",-1)])]),_:1}),l[27]||(l[27]=s(" 選題：",-1)),a(e,{href:"https://github.com/lkxed"},{default:n(()=>[...l[23]||(l[23]=[s("lkxed",-1)])]),_:1}),l[28]||(l[28]=s(" 譯者：",-1)),a(e,{href:"https://github.com/cyberwaddle"},{default:n(()=>[...l[24]||(l[24]=[s("cyberwaddle",-1)])]),_:1}),l[29]||(l[29]=s(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...l[25]||(l[25]=[s("wxy",-1)])]),_:1})]),i("p",null,[l[32]||(l[32]=s("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...l[30]||(l[30]=[s("LCTT",-1)])]),_:1}),l[33]||(l[33]=s(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:n(()=>[...l[31]||(l[31]=[s("Linux中國",-1)])]),_:1}),l[34]||(l[34]=s(" 榮譽推出",-1))])])}const T=p(d,[["render",u]]);export{f as __pageData,T as default};
